// DP：i 的 1 個數 = (i >> 1) 的 1 個數 + 最低位
// 時間複雜度: O(n)，空間複雜度: O(1)（不含輸出）
function countBits(n) {
    const ans = new Array(n + 1).fill(0);
    for (let i = 1; i <= n; i++) {
        ans[i] = ans[i >> 1] + (i & 1);
    }
    return ans;
}

solutions.python:
# 方法一：dp[i] = dp[i >> 1] + (i & 1)（推薦，最好記）
class Solution:
    def countBits(self, n: int) -> List[int]:
        dp = [0] * (n + 1)
        for i in range(1, n + 1):
            dp[i] = dp[i >> 1] + (i & 1)
        return dp


# 方法二：dp[i] = dp[i & (i-1)] + 1
class Solution:
    def countBits(self, n: int) -> List[int]:
        dp = [0] * (n + 1)
        for i in range(1, n + 1):
            dp[i] = dp[i & (i - 1)] + 1
        return dp


# 方法三：最高有效位
class Solution:
    def countBits(self, n: int) -> List[int]:
        dp = [0] * (n + 1)
        high_bit = 0
        for i in range(1, n + 1):
            if i & (i - 1) == 0:    # i 是 2 的冪
                high_bit = i
            dp[i] = dp[i - high_bit] + 1
        return dp

